        i -= 1
    if i == -1:
        # nums is the highest permutation; return the sorted (lowest) permutation
        return sorted(a)
    # Find the smallest element greater than a[i] to the right of i
    j = n - 1
    while a[j] <= a[i]:
        j -= 1
    # Swap a[i] and a[j]
    a[i], a[j] = a[j], a[i]
    # Reverse the suffix starting at i+1
    a[i+1:] = reversed(a[i+1:])
    return a

